<script setup lang="ts">import type{TableRow}from '../types/domain';import{fmt,pct,ratio}from '../utils/format';defineProps<{rows:TableRow[]}>();</script><template><div class="table-wrap"><table class="stratum-table"><thead><tr><th>预设分层</th><th>A成功 a</th><th>A失败 b</th><th>B成功 c</th><th>B失败 d</th><th>层内率 A / B</th><th>层内 OR</th><th>E[a] / Var[a]</th></tr></thead><tbody><tr v-for="t in rows" :key="t.code"><td><b>{{t.code}}</b><small>{{t.name}}</small><em v-if="!t.informative">无条件方差信息</em></td><td>{{t.a}}</td><td>{{t.b}}</td><td>{{t.c}}</td><td>{{t.d}}</td><td>{{pct(t.rate_a)}} / {{pct(t.rate_b)}}</td><td>{{ratio(t.odds_ratio)}}</td><td>{{fmt(t.expected_a,5)}} / {{fmt(t.variance_a,5)}}</td></tr></tbody></table><p v-if="!rows.length" class="empty">本研究尚无计数，请建立分层并填写四格。</p></div></template>
